// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

class ScalarExtensionSparqlRegressionTest {
	private static final String PREFIXES = "PREFIX xsd:<http://www.w3.org/2001/XMLSchema#> "
			+ "PREFIX mathf:<http://rdf4j.org/function/math#> PREFIX dtf:<http://rdf4j.org/function/datetime#> "
			+ "PREFIX strf:<http://rdf4j.org/function/string#> PREFIX jsonf:<http://rdf4j.org/function/json#> ";
	private static SailRepository repository;

	@BeforeAll
	static void startRepository() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterAll
	static void stopRepository() {
		repository.shutDown();
	}

	@Test
	void malformedNumbersAndEpochRangesRespectBindAndFilterBoundaries() {
		for (String expression : List.of("mathf:round(\"bad\"^^xsd:decimal,2)",
				"mathf:trunc(\"bad\"^^xsd:float)", "mathf:sign(\"bad\"^^xsd:integer)",
				"mathf:decimalFormat(\"bad\"^^xsd:decimal,\"0.00\")", "dtf:fromUnixtime(31556889864403200)")) {
			List<BindingSet> rows = query("SELECT ?x WHERE { BIND(" + expression + " AS ?x) }");
			assertThat(rows).as(expression).hasSize(1);
			assertThat(rows.get(0).hasBinding("x")).as(expression).isFalse();
			assertThat(query("SELECT ?keep WHERE { VALUES ?keep {1} FILTER(STR(" + expression + ") != \"\") }"))
					.as(expression)
					.isEmpty();
		}
	}

	@Test
	void oversizedCalculatedIndicesAndRepeatCountsLeaveBindUnbound() {
		for (String expression : List.of("strf:left(\"abc\",18446744073709551617 + 0)",
				"strf:repeat(\"ab\",9223372036854775807)")) {
			List<BindingSet> rows = query("SELECT ?x WHERE { BIND(" + expression + " AS ?x) }");
			assertThat(rows).as(expression).hasSize(1);
			assertThat(rows.get(0).hasBinding("x")).as(expression).isFalse();
		}
	}

	@Test
	void jsonConstructionAndExtractionPreserveExactRdfTerms() {
		List<BindingSet> rows = query("SELECT ?source ?actual WHERE { VALUES ?source {"
				+ "\"INF\"^^xsd:double \"NaN\"^^xsd:double \"1.5\"^^xsd:float \"01\"^^xsd:integer "
				+ "\"1\"^^xsd:int \"1\"^^xsd:boolean \"bad\"^^xsd:boolean } "
				+ "BIND(jsonf:jsonValue(jsonf:jsonArray(?source),\"$[0]\") AS ?actual) }");
		assertThat(rows).hasSize(7);
		for (BindingSet row : rows) {
			assertThat(row.getValue("actual")).isEqualTo(row.getValue("source"));
		}
	}

	@Test
	void tupleStringExtractionPreservesThePartsLanguage() {
		for (String call : List.of("strf:split", "strf:regexpExtractAll")) {
			String pattern = call.endsWith("split") ? "," : "[a-z]";
			List<BindingSet> rows = query("SELECT ?part WHERE { VALUES ?source { \"a,b\"@en } "
					+ "(?source \"" + pattern + "\") " + call + " ?part }");
			assertThat(rows).hasSize(2);
			assertThat(rows).extracting(row -> ((Literal) row.getValue("part")).getLanguage().orElse(""))
					.containsExactly("en", "en");
			assertThat(rows).extracting(row -> row.getValue("part").stringValue()).containsExactly("a", "b");
		}
	}

	private static List<BindingSet> query(String sparql) {
		try (var connection = repository.getConnection();
				var result = connection.prepareTupleQuery(PREFIXES + sparql).evaluate()) {
			return QueryResults.asList(result);
		}
	}
}
